}
.eon8-live-page .proposal-box {
    padding: 10px 30px;
    border-radius: 12px;
    box-shadow: 0 8px 25px rgba(0,0,0,0.05);
}
.eon8-live-page .proposal-title {
    font-size: 28px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 25px;
    line-height: 1.4;
}
.eon8-live-page .proposal-title strong {
    color: #f58322;
}
.eon8-live-page .proposal-btn {
    display: inline-block;
    background: linear-gradient(90deg, #f58322, #ff9c47);
    color: #fff;
    padding: 14px 28px;
    font-size: 16px;
    font-weight: 600;
    text-transform: uppercase;
    border-radius: 6px;
    text-decoration: none;
    transition: all 0.3s ease;
}
.eon8-live-page .proposal-btn:hover {
    background: linear-gradient(90deg, #e06f10, #ff8c2a);
    transform: translateY(-2px);
    box-shadow: 0 6px 15px rgba(245, 131, 34, 0.3);
}
